


/** The quantity state of one inventory item at one Location. */ export type InventoryLevel = { /** Derived and never written: on_hand minus unavailable, held, committed, and safety stock. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_quantity": string; /** Units promised to accepted orders. Still physically present until fulfillment consumes them. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "committed_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** On-hand units known to be damaged. Not sellable. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "damaged_quantity": string; /** Units claimed by an open reservation that has not been committed. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "held_quantity": string; /** Units recorded as inbound but not yet on hand. Does not count toward availability. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "incoming_quantity": string; /** The inventory item this level belongs to. Present only when the list request asked for expand=inventory_item. */ "inventory_item"?: { /** Optional searchable barcode. */ "barcode"?: string; /** Time the inventory item was created. Format: date-time. */ "created_at": string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Stable inventory item ID. */ "inventory_item_id": string; /** Caller-owned metadata. */ "metadata": Record<string, string>; /** Merchant-facing inventory item name. */ "name": string; /** Optional searchable stock-keeping unit. */ "sku"?: string; /** Current inventory item lifecycle status. */ "status": "active" | "inactive" | "archived" | (string & {}); /** Time the inventory item last changed. Format: date-time. */ "updated_at": string; /** Optimistic-concurrency version for item writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; }; "inventory_item_id": string; /** Advances only when held or committed quantities change. Use an exact numeric string, not a floating-point number. Format: int64. */ "inventory_level_claim_revision": string; "inventory_level_id": string; /** Advances only when on-hand or condition quantities change. Use an exact numeric string, not a floating-point number. Format: int64. */ "inventory_level_physical_revision": string; "location_id": string; /** Units physically present at the Location, in any condition. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "on_hand_quantity": string; /** On-hand units awaiting inspection. Not sellable. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quality_control_quantity": string; /** On-hand units isolated for review. Not sellable. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quarantined_quantity": string; /** Buffer withheld from allocation. Change it with PATCH /v1/inventory-levels/{inventory_level_id}. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "safety_stock_quantity": string; /** Derived: claims exceeding sellable physical stock. Positive only after stock is lost, damaged, or corrected down. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "shortage_quantity": string; /** Derived: quality_control + damaged + quarantined. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "unavailable_on_hand_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Advances on any quantity change at this level. Use an exact numeric string, not a floating-point number. Format: int64. */ "version": string; };
